			font-size: 30px;
			font-weight: bold;
		}
	</style>
</head>
<body>
	<table>
		<tr>
			<th onclick="marcar(this)">-</th>
			<th onclick="marcar(this)">-</th>
			<th onclick="marcar(this)">-</th>
		</tr>
		<tr>
			<th onclick="marcar(this)">-</th>
			<th onclick="marcar(this)">-</th>
